export function getComunaFeature(comunaStr) {
  if (!comunaStr) return null;
  const comunaMatch = comunaStr.match(/comuna\s*(\d+)/i);
  const targetId = comunaMatch ? comunaMatch[1] : (comunaStr.match(/\d+/) ? comunaStr.match(/\d+/)[0] : null);

  return COMUNAS_GEOJSON.find(c => {
    if (targetId && c.id === targetId) return true;
    return comunaStr.toLowerCase().includes(c.nombre.toLowerCase());
  }) || null;
}
